import sys,ast,types
sys.dont_write_bytecode=True
import additional_pfp_tests_remaining_audit as a
p='pfp/tests/adversarial_tier5/test_tier5_adversarial_m1_m3.py'
a.record(p,1,1218,'Full body read in contiguous chunks. Cemetery tests exercise tail truncation, individual entry tampering, extra keys, discontinuous index, BOM and authority-label refusals, but do not attack coherent ledger rewriting or external anchors. Sanitization explicitly maps Fraction/Q to strings and set/tuple to lists; no reversible typed roundtrip supports its zero-data-loss phrase. Q constructor/reduction and float refusal controls meaningful; injected Bareiss mock tests one triangular determinant and one symmetric PD matrix, while rank is hardcoded len and characteristic polynomial constant. Immune tests cover finite supplied regex panel, four Boolean signal combinations, exact toxicity examples, parent-child receipt/decay metadata; no empirical immune efficacy or general detection guarantee. Operad tests check nominal roles/type-slot splicing and permission sets, not laws/semantic repair independence. Cryptographic prefix admission correctly refuses, no valid human grant verification tested. Elenchus two canned regex triggers, Hill exact 1/17 and16/17 checked, kinetic proofreader accepts supplied initial_phi1=0 and equation-looking prose without formal proof. Retraction test accepts all three normal outcome classes and does not require child_state None despite its stricter stated invariant (F010). No module imports or test execution by audit.')
q='pfp/tests/adversarial_tier5/test_tier5_adversarial_m4_m5.py'
a.record(q,1,1059,'Full body read in contiguous chunks. Meaningful finite constructor/range/type/arity/zero-support controls, rational 1/3,2/3 renormalization, discontinuous path and divergent join failures, reversal and protected-pair projection examples. Information cohomology nilpotence is a method Boolean on supplied coefficients; no coboundary matrix is instantiated. Quarantine isolation is string-name checking; purported mutant is an unrelated lambda plus assertion of known False. Genesis apparatus set is constructed in test itself; pin is literal equality. Tower exhausts both singleton relations but only compares pinned strings for two-element stages, not the claimed16-relation computation. AST exactness uses caller-supplied zero residuals. CitationAnchor verified=True and Lean bridge PASS/hash/theorem names are supplied metadata, no source-byte/Lean verification. Native-refusal preservation test only counts three literal codes (F011). Sovereignty arithmetic99-56 gives43 but refusal label supplied. LP fixture is sound optimum5 for |3-a|+|2+a|, with five useful inconsistent certificate mutants; several mutants violate multiple conditions so do not isolate individual checks. RationalDualityGap equality alone has no primal/dual feasibility premise. Protocol isinstance tests only method presence on mocks (including always-True Lean verifier), not correct signatures, implementations, architecture or kernel proof. No module imports/native execution.')
n=a.read('_notes.json')
tree=ast.parse('\n'.join(a.source(p)))
node=next(x for x in ast.walk(tree) if isinstance(x,ast.Assert) and x.lineno==1217)
check=compile(ast.Expression(node.test),'<reviewed-assert-1217>','eval')
verdict=types.SimpleNamespace(REFUSAL='REFUSAL',DESCENT='DESCENT',EXACT='EXACT')
results={v:eval(check,{'StepVerdict':verdict,'outcome':types.SimpleNamespace(verdict=v)}) for v in ('REFUSAL','DESCENT','EXACT')}
