ev=lambda path,start,end:{'path':path,'sha256':a.row(path)['sha256'],'lines':[start,end]}
n['controls'].append({'id':'PFPTESTS-C009','rule':'strict_descent_assertion_discrimination','status':'all_three_outcome_classes_accepted','source_evidence':[ev(p,1191,1218)],'method':'Compiled only the fully read line1217 assertion expression with inert SimpleNamespace stand-ins; no test/domain imports or execution.','results':results})
n['findings'].append({'id':'PFPTESTS-F010','severity':'medium','statement':'Strict-descent adversarial test does not require refusal for its non-improving proposal.','evidence':[ev(p,1191,1218)],'control':'PFPTESTS-C009','reason':'Docstring requires REFUSAL and no child, but assertion permits REFUSAL, DESCENT and EXACT and checks only authority_effect afterward. An implementation accepting this empty proposal can satisfy the test.','limits':'Test adequacy finding; no new runtime acceptance claim or broad test execution.'})
n['findings'].append({'id':'PFPTESTS-F011','severity':'low','statement':'Native-refusal preservation test never calls a native runtime or a refusal mapper.','evidence':[ev(q,704,734)],'reason':'After timeout value-object tests, asserted refusal distinctness is len(set((three fixed string literals)))==3. Collapsing production refusal codes would not affect it.','limits':'This test alone supplies no code-preservation evidence; other native tests may cover that behavior.'})
n['claims'].append({'id':'PFPTESTS-CL006','statement':'Tier5 suites mix real finite boundary checks with metadata constructors and test-local constants; they are not aggregate mathematical or native-verification evidence.','evidence':[ev(p,584,624),ev(p,1170,1181),ev(q,554,608),ev(q,775,876),ev(q,882,911),ev(q,971,1059)],'limits':'Source review only. Exact dual fixture supports a finite LP example; no general kernel proof, biological efficacy, universal detector or exhaustive architecture claim.'})
